import {PIECES,allGeometricPlacements,aggregateMasks,tilingKey} from './batch-geometry.mjs';
import {buildVariants,createQueueOrderProjector} from './batch-orders.mjs';
function popcountBigInt(v){let n=0;for(;v;v&=v-1n)n++;return n}
export function maxPieceCounts(queues){const max=Object.fromEntries(PIECES.map(p=>[p,0]));for(const q of queues){const c=Object.fromEntries(PIECES.map(p=>[p,0]));for(const p of q)c[p]++;for(const p of PIECES)max[p]=Math.max(max[p],c[p])}return max}
export function enumerateTilings({fill,height=4,maxCounts=Object.fromEntries(PIECES.map(p=>[p,10])),maxSolutions=20000}){if(fill===0n)return[[]];const byCell=new Map();for(const p of PIECES)for(const mask of allGeometricPlacements(p,height)){if((mask&fill)!==mask)continue;for(let i=0;i<height*10;i++){const b=1n<<BigInt(i);if(mask&b){const a=byCell.get(i)??[];a.push({piece:p,mask});byCell.set(i,a)}}}const out=[],keys=new Set(),counts=Object.fromEntries(PIECES.map(p=>[p,0]));function rec(rem,ops){if(out.length>=maxSolutions)return;if(rem===0n){const k=tilingKey(ops);if(!keys.has(k)){keys.add(k);out.push([...ops])}return}
 // MRV: branch on the remaining cell with the fewest currently legal placements.
 let best=null,bestOps=null;for(let idx=0;idx<height*10;idx++){const b=1n<<BigInt(idx);if(!(rem&b))continue;const candidates=[];for(const op of byCell.get(idx)??[])if(counts[op.piece]<maxCounts[op.piece]&&(op.mask&rem)===op.mask)candidates.push(op);if(!candidates.length)return;if(bestOps===null||candidates.length<bestOps.length){best=idx;bestOps=candidates;if(candidates.length===1)break}}void best;for(const op of bestOps){counts[op.piece]++;ops.push(op);rec(rem^op.mask,ops);ops.pop();counts[op.piece]--}}rec(fill,[]);if(out.length>=maxSolutions)throw new Error(`congruent tiling limit ${maxSolutions} reached`);return out}
export function findCongruentSolutions({base,fill,queues,height=4,reachability,useHold=true}){const pieceCount=popcountBigInt(fill)/4,accelerated=pieceCount<=4?reachability?.congruent?.({base,fill,queues,useHold}):null;if(accelerated!==null&&accelerated!==undefined)return accelerated.map(({operations,orders})=>{const preferred=orders.includes('ZIS')?'ZIS':[...orders].sort().at(-1);return{operations,masks:aggregateMasks(operations),orders,comment:preferred,key:tilingKey(operations)}});const maxCounts=maxPieceCounts(queues),tilings=enumerateTilings({fill,height,maxCounts}),out=[],projector=createQueueOrderProjector(queues);for(const ops of tilings){const variants=buildVariants({base,operations:ops,height,reachability}),orders=[...new Set(variants.map(v=>v.order))],valid=projector.validOrders(orders,useHold);if(!valid.length)continue;const validSet=new Set(valid),preferred=valid.includes('ZIS')?'ZIS':[...valid].sort().at(-1);out.push({operations:ops,masks:aggregateMasks(ops),orders:valid,variants:variants.filter(v=>validSet.has(v.order)),comment:preferred,key:tilingKey(ops)})}return out}
